def keystone_auth_filter_factory(global_config, **local_config):
    global_config.update(local_config)
    config_file_name = global_config.get('config_file')
    if not config_file_name:
        raise ValueError("No config file specified")
    config_file = ConfigParser.SafeConfigParser()
    try:
        result = config_file.read(config_file_name)
        if not result:
            raise ValueError("Cannot read config file " + config_file_name)
        if not config_file.has_section('keystone_authtoken'):
            raise ValueError("Config file " + config_file_name + " does not have a [keystone_authtoken] section")
        global_config.update(config_file.items('keystone_authtoken'))
    except ConfigParser.ParsingError:
        raise ValueError("Cannot parse config file " + config_file_name)
    return auth_filter_factory(global_config)

